skills.contentCode:
Effect.heal(actor, 100);
Effect.modifyAttack(actor, 20, 5);
Effect.modifyMoveRange(actor, 2, 5);

// 在十字3格范围内选择一名敌人，造成 1.5 倍攻击力伤害
const ally = await Effect.chooseAlly(actor, {
  range: { shape: 'r', n: 4 },
  passThrough: true,
  hintText: '请选择友方'
});
if (!ally) return false;
Effect.heal(ally, 50);
actor.skilled = true;

const ally1 = await Effect.chooseAlly(actor, {
    range: { shape: 'r', n: 3 },
    passThrough: false,
    hintText: '请选择友方1'
  });
if (!ally1) return false;
const ally2 = await Effect.chooseAlly(actor, {
    range: { shape: 'r', n: 3 },
    passThrough: false,
    hintText: '请选择友方2',
    filter:function (cell,piece){
      return piece!=ally1
    }
  });
if (!ally2) return false;
Effect.swap(ally1, ally2);
actor.skilled = true;

if (!Game) return;
const allies = Game.pieces.filter(p => p.alive && p.side === actor.side);
let restored = 0;
for (const ally of allies) {
  if (!ally.cdMap) continue;
  for (const sk of (ally.skills || [])) {
    const cd = ally.cdMap[sk.id] || 0;
    if (cd > 0 && cd !== 2) {
      ally.cdMap[sk.id] = cd - 1;
      restored++;
    }
  }
}
if (restored > 0) {
  Game.log('【英姿】' + actor.name + ' 激励全军，恢复 ' + restored + ' 个技能冷却！', 'turn');
}

const cells = Range.cellsInRange("square", 1, actor.x, actor.y, { includeSelf: false });
for (const c of cells) {
  const t = Game.pieceAt(c.x, c.y);
  if (t && t.alive && t.side !== actor.side){
    var dir = [Math.sign(t.x-actor.x)||0, Math.sign(t.y-actor.y)||0];
    Effect.push(actor, t, dir, 1);
  }
}
return true;

// contentCode
var data = Effect.getMarkData(actor, "charge_form");
var form = data ? data.form : 1;

var cells = Range.cellsInRange("square", 1, actor.x, actor.y, { includeSelf: false });
var enemies = [];
for (var i = 0; i < cells.length; i++) {
  var p = Game.pieceAt(cells[i].x, cells[i].y);
  if (p && p.alive && p.side !== actor.side) enemies.push(p);
}

if (form === 1) {
  // 形态1：30点无视防御伤害
  for (var i = 0; i < enemies.length; i++) {
    Effect.damage(actor, enemies[i], 30, { ignoreDef: true });
    Effect.fx.shake(enemies[i], { intensity: 5, duration: 350 });
  }
  Effect.fx.ring(actor.x, actor.y, { color: "#f80", duration: 500 });
  Game.log(actor.name + " 发动【冲阵·形态1】，对周围敌人造成30点伤害！");
  form = 2;
} else {
  // 形态2：推开敌人 + 回血20
  for (var i = 0; i < enemies.length; i++) {
    var t = enemies[i];
    var dx = Math.sign(t.x - actor.x);
    var dy = Math.sign(t.y - actor.y);
    if (dx === 0 && dy === 0) continue;
    Effect.push(actor, t, [dx, dy], 1);
  }
  Effect.heal(actor, 15);
  Effect.fx.pulse(actor, { color: "#4f4", duration: 500 });
  Game.log(actor.name + " 发动【冲阵·形态2】，推开敌人并恢复20点生命！");
  form = 1;
}
Effect.unmark(actor, 'charge_form');
Effect.mark(actor, 'charge_form', { display: '形态'+form, modifiers: {}, data: {form:form} });

// contentCode
if (actor.moved) return;
Game.log(actor.name + " 发动【突围】，触发移动后时机！");
Effect.triggerPassive(actor, "onMove", {
  from: { x: actor.x, y: actor.y },
  to: { x: actor.x, y: actor.y }
});

// contentCode
var data = Effect.getMarkData(actor, "qinglong");
var stacks = data ? (data.stacks || 0) : 0;
if (stacks >= 3) {
  Game.log(actor.name + " 青龙标记已满（3/3）。");
  return false;
}
actor.skilled = true;
actor.attacked = true;
Effect.unmark(actor, "qinglong");
Effect.mark(actor, "qinglong", {
  display: "青"+(stacks+1),
  data: { stacks: stacks + 1 }
});
Effect.fx.glow(actor, { color: "#4af", duration: 600 });
Game.log(actor.name + " 发动【青龙】，获得青龙标记（" + (stacks + 1) + "/3）。");
return true;

// contentCode
if (!context || !context.target) return;
var t = context.target;
if (!t.alive) return;
var data = Effect.getMarkData(actor, "qinglong");
var stacks = data ? (data.stacks || 0) : 0;

// 1. 25%概率眩晕敌人，成功则回血并清空所有青龙标记
if (Effect.chance(0.25)) {
  Effect.stun(t, 1);
  Effect.fx.shake(t, { axis: "r", intensity: 6, duration: 400 });
  Effect.fx.beam(actor.x, actor.y, t.x, t.y, { color: "#f44", width: 10, duration: 350 });
  Game.log(actor.name + " 发动【武圣】，眩晕 " + t.name + "！");
  if (stacks > 0) {
    var healAmt = 20 * stacks;
    Effect.heal(actor, healAmt);
    Effect.fx.pulse(actor, { color: "#4f4", duration: 500 });
    Game.log(actor.name + " 恢复 " + healAmt + " 点生命，失去所有青龙标记。");
    Effect.unmark(actor, "qinglong");
    stacks = 0;
  }
}

// 2. 若仍有青龙标记，恢复攻击并减一个标记
if (stacks > 0) {
  Effect.resetAttack(actor);
  var remain = stacks - 1;
  Effect.unmark(actor, "qinglong");
  if (remain > 0) {
    Effect.mark(actor, "qinglong", {
      display: "青"+remain,
      data: { stacks: remain }
    });
  }
  Effect.fx.glow(actor, { color: "#ffcc00", duration: 500 });
  Game.log(actor.name + " 发动【武圣】，消耗一个青龙标记，恢复攻击（剩余 " + remain + " 个）。");
}

// contentCode
// 选择方形三格内的空格传送
cell=await Effect.chooseCell(actor, {
    range: { shape: 'square', n: 3 },
    mustEmpty: true,
    hintText: '请选择传送目标格（方形3格内空地）'
  })
if (!cell) {
  Game.log(actor.name + ' 取消传送。');
  return false;
}
// 传送
var fromX = actor.x, fromY = actor.y;
Effect.teleport(actor, cell.x, cell.y);
Game._render();
Effect.fx.particles(fromX, fromY, { color: '#fff', count: 14, spread: 50, duration: 500 });
Effect.fx.particles(cell.x, cell.y, { color: '#fff', count: 14, spread: 50, duration: 500 });
Game.log(actor.name + ' 发动【白马】，传送到 (' + cell.x + ',' + cell.y + ')。');

// 对以自己为中心的□形1格内所有敌人造成100%伤害
var cells = Range.cellsInRange('square', 1, actor.x, actor.y, { includeSelf: false });
var enemies = [];
for (var i = 0; i < cells.length; i++) {
  var p = Game.pieceAt(cells[i].x, cells[i].y);
  if (p && p.alive && p.side !== actor.side) enemies.push(p);
}
var dmg = Effect.getEffectiveAttack(actor);  // 100%攻击力
for (var j = 0; j < enemies.length; j++) {
  Effect.damage(actor, enemies[j], dmg);
  Effect.fx.shake(enemies[j], { intensity: 5, duration: 350 });
}
Effect.fx.ring(actor.x, actor.y, { color: '#ffeebb', maxRadius: 90, duration: 500 });
Game.log(actor.name + ' 白马冲击命中 ' + enemies.length + ' 名敌人！');

// 根据命中数量 X，获得移动范围 +X 增益，持续2回合
var X = enemies.length;
if (X > 0) {
  Effect.addMark(actor, 'baima_buff', 2, {
      display: '移动+'+X,
      modifiers: { moveRangeDelta: X }
    });
  Effect.fx.glow(actor, { color: '#ffeebb', duration: 600 });
  Game.log(actor.name + ' 获得「白马」增益：移动范围 +' + X + '（持续2回合）。');
}
actor.skilled = true;
actor.moved=false;
return true;

skills.filterCode:
// filterCode
var hpRatio = actor.hp / (actor.maxHp || 200);
if (hpRatio >= 0.5) return;
return actor && actor.alive;

skills.contentCode:
// contentCode
if (!context || !context.attacker) return;
// 血量低于50%才触发
var hpRatio = actor.hp / (actor.maxHp || 200);
if (hpRatio >= 0.5) return;

// 把 diyminion_baimayicong 加入手牌，消耗设为0
var card = Effect.addCard('diyminion_baimayicong',actor.side);
if (card) {
  card.cost = 1;  // 强制消耗为0
  Effect.fx.glow(actor, { color: '#fff', duration: 500 });
  Game.log(actor.name + ' 发动【义从】，获得一张消耗为0的「白马义从」！');
}

actor.attacked = true;
var d = Effect.getMarkData(actor, 'shensu');
var x=d.num+1
Effect.unmark(actor, 'shensu');
Effect.mark(actor, 'shensu', { display: '神速'+x, modifiers: {}, data: {num:x} });

const choice = await Effect.chooseOption(actor, {
  title: '请选择',
  hintText: '发动分支技能！',
  options: [
    { label: '变易', desc: '恢复移动', value: 'chng', aiScore: 70, aiCondition: function(a) { return !!a.moved; } },
    { label: '强攻', desc: '立即攻击', value: 'atk', aiScore: 70, aiEval: function(a) {
      for (var dx = -1; dx <= 1; dx++) for (var dy = -1; dy <= 1; dy++) {
        var p = Game.pieceAt(a.x + dx, a.y + dy);
        if (p && p.alive && p.side !== a.side) return 60;
      }
      return 0;
    } },
    { label: '治疗', desc: '回 30 血', value: 'heal', aiScore: 80, aiCondition: function(a){ return a.hp < a.maxHp * 0.6; } }
  ]
});
if (!choice) return false;
if (choice.value === 'atk') {
const target = await Effect.chooseEnemy(actor, {
  range: { shape: '+', n: 1 },
  passThrough: true,
  hintText: '请选择敌人'
});
if (!target) return false;
Effect.basicAttack(actor, target);
}
else if (choice.value === 'heal') Effect.heal(actor, 30);
else if (choice.value === 'chng') Effect.resetMove(actor);
Effect.playSkillCastSound(actor,actor.skills[1])
var d = Effect.getMarkData(actor, 'shensu');
var x=d.num-1
Effect.unmark(actor, 'shensu');
Effect.mark(actor, 'shensu', { display: '神速'+x, modifiers: {}, data: {num:x} });

return true;

const cell = await Effect.chooseCell(actor, {
    range: { shape: 'square', n: 2 },
    mustEmpty: true,
    passThrough: false,
    //filter: function(cell, piece) { return cell.x >= 3; },
    hintText: '请选择目标格'
  });
if (!cell) return false;
Effect.placeTrap(cell.x,cell.y, {
    owner: actor,
    side: 'enemy',
    // step：只有踩到终点时触发
    // pass：经过路径上的格子时触发，包含最终落脚格
    mode: 'pass',
    data: {
      amount: 30
    },
    turns:3,
    callback: function (piece, trap, context) {
      const source = trap.owner && trap.owner.alive ? trap.owner : null;
      Effect.damage(null, piece, trap.data.amount, {
          ignoreDef: true
        });
      Effect.stun(piece, 1);
      Effect.playSkillHitSound(trap.owner.skills[0])
      Game.log(piece.name + ' 触发了自定义陷阱！');
    }
  });
actor.skilled = true;

var from = context && context.from;
if (!from) return false;
var dist = Math.abs(from.x - actor.x) + Math.abs(from.y - actor.y);
if (dist < 3) return false;
var best = null, bestD = 999;
var list = Effect.getEnemies(actor);
for (var i = 0; i < list.length; i++) {
  var e = list[i];
  var d = Math.abs(e.x - actor.x) + Math.abs(e.y - actor.y);
  if (d < bestD) { bestD = d; best = e; }
}
if (!best || bestD > 4) return false;
Effect.damage(actor, best, 30);
Effect.modifyAttack(best, -10, 1);
Game.log('【突袭】' + actor.name + ' 长途奔袭，' + best.name + ' 受到30点伤害且攻击下降。');
return true;

var target = await Effect.chooseEnemy(actor, {
  range: { shape: '+', n: 3 },
  passThrough: true,
  hintText: '选择单挑目标'
});
if (!target) return false;
var dirs = [[0, -1], [0, 1], [-1, 0], [1, 0]];
var spot = null, sd = 999;
for (var i = 0; i < dirs.length; i++) {
  var nx = actor.x + dirs[i][0], ny = actor.y + dirs[i][1];
  if (nx < 0 || ny < 0 || nx >= Range.BOARD_SIZE || ny >= Range.BOARD_SIZE) continue;
  if (Game.pieceAt(nx, ny)) continue;
  var d = Math.abs(target.x - nx) + Math.abs(target.y - ny);
  if (d < sd) { sd = d; spot = { x: nx, y: ny }; }
}
if (!spot) { Game.log('【威震逍遥津】' + actor.name + ' 周围没有落脚处。'); return false; }
Effect.teleport(target, spot.x, spot.y);
Game.log('【威震逍遥津】' + actor.name + ' 将 ' + target.name + ' 拽到阵前，单挑开始！', 'turn');
var actorFirst = Effect.getEffectiveAttack(actor) >= Effect.getEffectiveAttack(target);
if (actorFirst) {
  Effect.basicAttack(actor, target);
  if (target.alive) Effect.basicAttack(target, actor);
} else {
  Effect.basicAttack(target, actor);
  if (actor.alive) Effect.basicAttack(actor, target);
}
actor.skilled = true;
return true;

var t = context && context.target;
if (!t || !t.alive) return false;
if (Game.__liegongBusy) return false;
var d = Math.abs(t.x - actor.x) + Math.abs(t.y - actor.y);
if (d < 3) return false;
Game.__liegongBusy = true;
try {
  Effect.damage(actor, t, 20, { ignoreDef: true });
  Game.log('【烈弓】' + actor.name + ' 远距离劲射，' + t.name + ' 额外受到20点伤害。');
  if (t.alive && Effect.hasMark(actor, 'aim')) {
    Effect.unmark(actor, 'aim');
    Effect.damage(actor, t, 20, { ignoreDef: true });
    Game.log('【百步】瞄准命中要害，追加20点伤害！');
  }
} finally {
  Game.__liegongBusy = false;
}
return true;

if (!actor.moved) {
  Effect.mark(actor, 'aim', { display: '瞄准', modifiers: { attackRangeDelta: 1 }, data: {} });
  Game.log('【百步】' + actor.name + ' 原地瞄准，射程提升。');
} else {
  Effect.unmark(actor, 'aim');
}
return true;

var target = await Effect.chooseEnemy(actor, {
  range: { shape: '+', n: 4 },
  passThrough: true,
  hintText: '选择穿透方向上的敌人'
});
if (!target) return false;
var dx = 0, dy = 0;
if (Math.abs(target.x - actor.x) >= Math.abs(target.y - actor.y)) dx = Math.sign(target.x - actor.x);
else dy = Math.sign(target.y - actor.y);
if (dx === 0 && dy === 0) return false;
var amounts = [60, 45, 30];
var x = actor.x + dx, y = actor.y + dy, hit = 0;
while (x >= 0 && y >= 0 && x < Range.BOARD_SIZE && y < Range.BOARD_SIZE) {
  var p = Game.pieceAt(x, y);
  if (p && p.alive) {
    if (p.side === actor.side) break;
    var amt = amounts[Math.min(hit, amounts.length - 1)];
    Effect.damage(actor, p, amt);
    Game.log('【穿云】贯通 ' + p.name + '，造成' + amt + '点伤害。');
    hit++;
  }
  x += dx; y += dy;
}
if (hit === 0) return false;
actor.skilled = true;
return true;

var cell = await Effect.chooseCell(actor, {
  range: { shape: '+', n: 4 },
  mustEmpty: true,
  passThrough: true,
  aiPrefer: 'aggressive',
  hintText: '选择突进落点'
});
if (!cell) return false;
Effect.teleport(actor, cell.x, cell.y);
Effect.mark(actor, 'qimou', { display: '奇谋', modifiers: { attackRangeDelta: 1 }, data: {} });
actor.attacked = true;
actor.skilled = true;
Game.log('【子午谷】' + actor.name + ' 突进至 (' + cell.x + ',' + cell.y + ')，蓄势待发。', 'turn');
return true;

var t = context && context.target;
if (!t || !t.alive) return false;
if (!Effect.hasMark(actor, 'qimou')) return false;
Effect.unmark(actor, 'qimou');
var extra = Math.max(1, Math.floor(Effect.getEffectiveAttack(actor) * 0.6));
Effect.damage(actor, t, extra, { ignoreDef: true });
Game.log('【奇谋】' + actor.name + ' 蓄势爆发，追加' + extra + '点伤害！', 'turn');
return true;

var lost = 1 - actor.hp / actor.maxHp;
var stacks = Math.min(4, Math.floor(lost / 0.2 + 0.0001));
Effect.unmark(actor, 'fangu');
if (stacks > 0) {
  Effect.mark(actor, 'fangu', { display: '反骨+' + (stacks * 8), modifiers: { atkBuff: stacks * 8 }, data: {} });
}
return true;

var target = await Effect.chooseEnemy(actor, {
  range: { shape: 'square', n: 2 },
  passThrough: true,
  hintText: '选择换位目标'
});
if (!target) return false;
Effect.swap(actor, target);
var dirs = [[0, -1], [0, 1], [-1, 0], [1, 0]];
var cnt = 0;
for (var i = 0; i < dirs.length; i++) {
  var p = Game.pieceAt(actor.x + dirs[i][0], actor.y + dirs[i][1]);
  if (p && p.alive && p.side !== actor.side) cnt++;
}
if (cnt >= 2) {
  Effect.shield(actor, 30);
  Game.log('【巧变】四面受敌，' + actor.name + ' 获得30点护盾。');
}
actor.skilled = true;
return true;

Effect.unmark(actor, 'liaodi');
var r = Effect.getEffectiveAttackRange(actor);
var cells = Range.cellsInRange(r.shape, r.n, actor.x, actor.y, { includeSelf: false });
var cnt = 0;
for (var i = 0; i < cells.length; i++) {
  var p = Game.pieceAt(cells[i].x, cells[i].y);
  if (p && p.alive && p.side !== actor.side) cnt++;
}
if (cnt >= 2) {
  Effect.mark(actor, 'liaodi', { display: '料敌+10', modifiers: { atkBuff: 10 }, data: {} });
}
return true;

Effect.modifyAttack(actor, 50, 1);
Effect.modifyDef(actor, -5, 1);
Effect.undying(actor, 1);
actor.skilled = true;
Game.log('【抬棺决战】' + actor.name + ' 抬棺而战，攻击大涨并获得不屈！', 'turn');
return true;

Effect.unmark(actor, 'sizhan');
if (actor.hp / actor.maxHp < 0.3) {
  Effect.mark(actor, 'sizhan', { display: '死战', modifiers: { atkBuff: 20, moveRangeDelta: 1 }, data: {} });
  Game.log('【死战】' + actor.name + ' 浴血奋战，攻击力提升。');
}
return true;

var a = await Effect.chooseEnemy(actor, {
  range: { shape: 'square', n: 4 },
  passThrough: true,
  hintText: '选择第一个目标'
});
if (!a) return false;
var list = Effect.getEnemies(actor).filter(function (e) {
  return e !== a && Math.abs(e.x - a.x) + Math.abs(e.y - a.y) <= 4;
});
if (!list.length) { Game.log('【连环】附近没有第二个可连结的目标。'); return false; }
var b = null;
if (Effect._aiContext && Effect._aiContext.mode) {
  list.sort(function (p, q) { return p.hp - q.hp; });
  b = list[0];
} else {
  b = await Effect.chooseEnemy(actor, {
    range: { shape: 'square', n: 4 },
  passThrough: true,
    filter: function (cell, piece) { return !!piece && list.indexOf(piece) >= 0; },
    hintText: '选择第二个目标'
  });
  if (!b) return false;
}
Effect.linkDamage(a, b, 2, 0.5);
actor.skilled = true;
Game.log('【连环】' + a.name + ' 与 ' + b.name + ' 被铁索相连！', 'turn');
return true;
